func TestPiReviewer_NameMatchesRegistryKey(t *testing.T) {
	t.Parallel()
	if got := NewReviewer().Name(); got != string(agent.AgentNamePi) {
		t.Fatalf("Name() = %q, want %q", got, agent.AgentNamePi)
	}
