			tokens = append(tokens, tok)
		}
	}
	if len(tokens) != 1 {
		t.Fatalf("token events = %d, want 1: %#v", len(tokens), events)
	}
	if got := tokens[0]; got.In != 10 || got.Out != 5 {
		t.Fatalf("Tokens = %#v, want In=10 Out=5", got)
